
$ErrorActionPreference = "Stop"

$root = Get-Location
$payloadZip = Join-Path $root ".frontend_full_wired_payload.zip"
$tempDir = Join-Path $root ".frontend_full_wired_payload"
$backupDir = Join-Path $root ("_frontend_backup_" + (Get-Date -Format "yyyyMMdd_HHmmss"))

function Write-Info($msg) { Write-Host "[frontend-rewire] $msg" -ForegroundColor Cyan }
function Copy-IfExists($src,$dst) { if (Test-Path $src) { Copy-Item $src $dst -Recurse -Force } }

Write-Info "Writing embedded payload zip..."
$b64 = @"

"@
@"

"@
@"

"@
@"

"@
@"

"@
@"

"@
[IO.File]::WriteAllBytes($payloadZip, [Convert]::FromBase64String(($b64 -join "")))

if (Test-Path $tempDir) { Remove-Item $tempDir -Recurse -Force }
Expand-Archive -Path $payloadZip -DestinationPath $tempDir -Force

Write-Info "Creating backup at $backupDir"
New-Item -ItemType Directory -Path $backupDir | Out-Null
Copy-IfExists (Join-Path $root "src") (Join-Path $backupDir "src")
Copy-IfExists (Join-Path $root "public") (Join-Path $backupDir "public")
Copy-IfExists (Join-Path $root "package.json") (Join-Path $backupDir "package.json")
Copy-IfExists (Join-Path $root "package-lock.json") (Join-Path $backupDir "package-lock.json")
Copy-IfExists (Join-Path $root "vite.config.ts") (Join-Path $backupDir "vite.config.ts")
Copy-IfExists (Join-Path $root "tailwind.config.ts") (Join-Path $backupDir "tailwind.config.ts")
Copy-IfExists (Join-Path $root "components.json") (Join-Path $backupDir "components.json")
Copy-IfExists (Join-Path $root "tsconfig.json") (Join-Path $backupDir "tsconfig.json")
Copy-IfExists (Join-Path $root "tsconfig.app.json") (Join-Path $backupDir "tsconfig.app.json")
Copy-IfExists (Join-Path $root "tsconfig.node.json") (Join-Path $backupDir "tsconfig.node.json")
Copy-IfExists (Join-Path $root "index.html") (Join-Path $backupDir "index.html")
Copy-IfExists (Join-Path $root "postcss.config.js") (Join-Path $backupDir "postcss.config.js")
Copy-IfExists (Join-Path $root "eslint.config.js") (Join-Path $backupDir "eslint.config.js")

Write-Info "Removing old frontend app files..."
$removeList = @(
  "src","public","package.json","package-lock.json","vite.config.ts","tailwind.config.ts","components.json",
  "tsconfig.json","tsconfig.app.json","tsconfig.node.json","index.html","postcss.config.js","eslint.config.js",
  "README.md","bun.lock","bun.lockb","playwright.config.ts","playwright-fixture.ts","vitest.config.ts"
)
foreach ($item in $removeList) {
  $path = Join-Path $root $item
  if (Test-Path $path) { Remove-Item $path -Recurse -Force }
}

Write-Info "Copying new wired frontend files..."
Copy-Item (Join-Path $tempDir "*") $root -Recurse -Force

Write-Info "Preserving Electron shell and env files."
# electron and .env files were never removed

Write-Info "Installing dependencies..."
Push-Location $root
npm install
if ($LASTEXITCODE -ne 0) { throw "npm install failed with exit code $LASTEXITCODE" }

Write-Info "Running frontend build verification..."
npm run build
if ($LASTEXITCODE -ne 0) { throw "npm run build failed with exit code $LASTEXITCODE" }
Pop-Location

Write-Info "Done. New wired frontend is in place."
Write-Info "You do NOT need the backend running to apply this replacement."
Write-Info "You SHOULD have the backend running when you open the app and test live data, chat, settings, projects, files, and tools."
